import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../providers/catalog_provider.dart'; import '../widgets/product_card.dart';
class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen> createState()=>_SearchScreenState();}
class _SearchScreenState extends State<SearchScreen>{final controller=TextEditingController();@override Widget build(BuildContext c){final products=c.watch<CatalogProvider>().search(controller.text);return Scaffold(appBar:AppBar(title:TextField(controller:controller,autofocus:true,onChanged:(_)=>setState((){}),decoration:const InputDecoration(hintText:'Search products...',prefixIcon:Icon(Icons.search),border:InputBorder.none))),body:products.isEmpty?const Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.search_off,size:56,color:Colors.grey),SizedBox(height:10),Text('No products found')])):GridView.builder(padding:const EdgeInsets.all(16),itemCount:products.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,crossAxisSpacing:12,mainAxisSpacing:12,childAspectRatio:.63),itemBuilder:(_,i)=>ProductCard(product:products[i])));}}
